export function publicationLabels(language='EN'){const index=Math.max(0,pubLanguages.indexOf(language));return Object.fromEntries(Object.entries(pubWords).map(([key,row])=>[key,row.split('|')[index]||row.split('|')[0]]));}

export function attachPublicationDesk({getLanguage=()=> 'EN',getCurrent=()=>null,getSeries=()=>null,storage=globalThis.localStorage,fetcher=(...args)=>fetch(...args)}={}){
 const host=document.querySelector('.custom-library-toolbar');if(!host||document.getElementById('publication-desk'))return null;
 let store=createPublicationStore(storage);let current=store.list().at(-1)||createPublicationDraft(),pending=false,statusKey=store.problem()?'saveError':'',searchToken=0,loadToken=0,page=0,query='',results=[],total=0,aiText='',projectSelect,progress,passport,keywordList;const fields=new Map();
 const t=()=>publicationLabels(getLanguage()),el=(tag,text='',cls='')=>{const n=document.createElement(tag);n.textContent=text;if(cls)n.className=cls;return n;};
 const root=el('details','','publication-desk');root.id='publication-desk';const summary=el('summary'),body=el('div','','pd-body');root.append(summary,body);host.after(root);
 const launcher=el('button');launcher.id='publication-desk-launcher';launcher.type='button';launcher.addEventListener('click',()=>open());host.append(launcher);
 const status=el('p','','pd-status');status.setAttribute('role','status');status.setAttribute('aria-live','polite');
 const notify=key=>{statusKey=key;status.textContent=t()[key]||key;};
 const open=()=>{root.open=true;root.scrollIntoView({behavior:'smooth',block:'start'});};
 function save(){try{store.save(current);pending=false;notify('saved');updateProjects();document.dispatchEvent?.(new CustomEvent('prompt-studio-work-changed',{detail:{kind:'publication',id:current.id}}));announce();return true;}catch(error){pending=true;notify(['conflict','limit'].includes(error.message)?error.message:'saveError');return false;}}
 function announce(){document.dispatchEvent?.(new CustomEvent('prompt-studio-publication-status',{detail:{seriesId:current.seriesId}}));}
 function updateProjects(){if(!projectSelect)return;const entries=store.list();if(!entries.some(d=>d.id===current.id))entries.push(current);projectSelect.replaceChildren(...entries.map(d=>new Option(d.id===current.id?current.name||t().name:d.name||t().name,d.id)));projectSelect.value=current.id;}
 const canLeave=()=>!pending||globalThis.confirm(t().unsaved);
 function select(draft){loadToken++;current=normalizePublicationDraft(draft);pending=false;aiText='';statusKey='';render();document.dispatchEvent?.(new CustomEvent('prompt-studio-work-opened',{detail:{kind:'publication',id:current.id}}));}
 function capture(draft){if(!canLeave())return false;select(draft);save();open();return true;}
 function edit(fn,textChanged=false){fn();if(textChanged)current.checks.text=false;save();refresh();}
 function button(parent,key,fn){const b=el('button',t()[key]);b.type='button';b.dataset.pdAction=key;b.addEventListener('click',fn);parent.append(b);return b;}
 function field(parent,key,value,type='text',handler,labelKey=key){const label=el('label'),caption=el('span',t()[labelKey]||labelKey),input=el(type==='textarea'?'textarea':type==='select'?'select':'input');if(!['textarea','select'].includes(type))input.type=type;input.dataset.pdField=key;input.value=String(value??'');if(type==='textarea'){input.rows=key.endsWith('description')?7:3;input.maxLength=key==='aiAnswer'?50000:14000;}else input.maxLength=key==='query'?500:180;if(handler)input.addEventListener(type==='select'?'change':'input',()=>handler(input.value));label.append(caption,input);parent.append(label);fields.set(key,input);return input;}
 function checkbox(parent,key,value,handler,labelKey=key){const label=el('label','','pd-check'),input=el('input');input.type='checkbox';input.checked=value;input.dataset.pdField=key;input.addEventListener('change',()=>handler(input.checked));label.append(input,el('span',t()[labelKey]));parent.append(label);fields.set(key,input);return input;}
 async function copy(value){try{await navigator.clipboard.writeText(value);notify('copied');}catch{notify('copyError');}}
 function download(data,suffix,type){const url=URL.createObjectURL(new Blob([data],{type})),a=el('a');a.href=url;a.download=(current.name.replace(/[^\p{L}\p{N}_-]+/gu,'_').slice(0,70)||'publication')+suffix;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function renderKeywords(){keywordList.replaceChildren();for(const keyword of current.keywords){const label=el('label','','pd-keyword'),input=el('input');input.type='checkbox';input.checked=keyword.selected;input.addEventListener('change',()=>edit(()=>keyword.selected=input.checked,true));label.append(input,el('span',keyword.text));keywordList.append(label);}}
 function refresh(){if(progress)progress.textContent=publicationReady(current)?t().ready:t().working;const review=fields.get('check-text');if(review)review.checked=current.checks.text;if(passport){const files=exportPublicationFiles(current);passport.value=files['creator-passport_'+(getLanguage()==='HU'?'HU':'EN')+'.txt']||files['plan-notes.txt']||'—';}}
 async function json(url){const response=await fetcher(url);if(!response.ok)throw Error('load');return response.json();}
 async function search(){const token=++searchToken;notify('loading');try{const data=await json('/api/catalog/search?'+new URLSearchParams({q:query,page:String(page)}));if(token!==searchToken)return;results=Array.isArray(data.results)?data.results:[];total=Number(data.total)||0;renderResults();notify('');}catch{if(token===searchToken)notify('loadError');}}
 let resultsBox;
 function renderResults(){if(!resultsBox)return;resultsBox.replaceChildren();for(const item of results){const b=el('button',(item.kind==='video'?'▶ ':'▧ ')+String(item.filename||item.id));b.type='button';b.dataset.pdArchiveId=String(item.id);b.addEventListener('click',async()=>{const token=++loadToken;notify('loading');try{const [base,detail]=await Promise.all([json('/api/catalog/item?id='+encodeURIComponent(item.id)),json('/api/catalog/settings?id='+encodeURIComponent(item.id))]);if(token===loadToken)capture(publicationFromArchive({...base,...detail}));}catch{if(token===loadToken)notify('loadError');}});resultsBox.append(b);}
  const pagination=el('div','','pd-actions');const previous=button(pagination,'previous',()=>{if(page>0){page--;void search();}}),next=button(pagination,'next',()=>{page++;void search();});previous.disabled=page===0;next.disabled=(page+1)*24>=total;pagination.append(el('span',(page+1)+' · '+total));resultsBox.append(pagination);
 }
 function render(){
  fields.clear();summary.textContent=t().title;launcher.textContent=t().title;body.replaceChildren(el('p',t().intro));
  const toolbar=el('div','','pd-actions');body.append(toolbar);projectSelect=field(toolbar,'drafts',current.id,'select',value=>{const next=store.list().find(d=>d.id===value);if(next&&canLeave())select(next);else projectSelect.value=current.id;});updateProjects();
  button(toolbar,'new',()=>{if(canLeave())select(createPublicationDraft());});button(toolbar,'save',save);button(toolbar,'remove',()=>{if(!globalThis.confirm(t().confirmRemove))return;try{store.remove(current.id);select(store.list().at(-1)||createPublicationDraft());announce();document.dispatchEvent?.(new CustomEvent('prompt-studio-work-changed',{detail:{kind:'publication'}}));}catch{notify('saveError');}});
  field(body,'name',current.name,'text',value=>edit(()=>current.name=value));const loaders=el('div','','pd-actions');body.append(loaders);button(loaders,'current',()=>capture(publicationFromCurrent(getCurrent()||{})));button(loaders,'series',()=>{const series=getSeries();if(series)capture(publicationFromSeries(series));else notify('none');});
  const sourceList=el('div','','pd-sources');sourceList.append(el('strong',t().sources));for(const source of current.sources)sourceList.append(el('p',source.name+' — '+t()[source.origin==='archive'?'archive':'plan']));body.append(sourceList);
  const searchArea=el('details','','pd-search');searchArea.append(el('summary',t().search));field(searchArea,'query',query,'text',value=>query=value);button(searchArea,'search',()=>{page=0;void search();});resultsBox=el('div','','pd-results');searchArea.append(resultsBox);body.append(searchArea);renderResults();
  field(body,'brief',current.brief,'textarea',value=>edit(()=>current.brief=value));body.append(el('p',t().briefHelp,'pd-help'));
  const copies=el('div','','pd-copy-grid');body.append(copies);for(const language of ['EN','HU']){const box=el('section','','pd-copy');box.append(el('h3',t()[language==='EN'?'english':'hungarian']));for(const key of ['title','teaser','description']){field(box,language+'_'+key,current.copy[language][key],key==='title'?'text':'textarea',value=>edit(()=>current.copy[language][key]=value,true),key==='title'?'titleText':key);const b=button(box,'copy',()=>copy(current.copy[language][key]));b.dataset.pdCopy=language+'_'+key;}copies.append(box);}
  field(body,'keywords',current.keywords.map(k=>k.text).join(', '),'textarea',value=>{edit(()=>current.keywords=publicationKeywords(value,current.keywords),true);renderKeywords();});body.append(el('p',t().keywordHelp,'pd-help'));keywordList=el('div','','pd-keywords');body.append(keywordList);renderKeywords();button(body,'copyTags',()=>copy(current.keywords.filter(k=>k.selected).map(k=>k.text).join(', ')));
  const ai=el('details','','pd-ai');ai.append(el('summary',t().ai));body.append(ai);button(ai,'ai',()=>{const request=publicationAiRequest(current);document.dispatchEvent(new CustomEvent('prompt-studio-ask-ai',{detail:{task:'custom',text:request.text,question:request.question}}));});field(ai,'aiAnswer',aiText,'textarea',value=>aiText=value);button(ai,'applyAi',()=>{const answer=aiText.trim()||document.getElementById('ai-hub-response')?.value||'';try{const next=applyPublicationAi(current,answer);if(!globalThis.confirm(t().confirmAi))return;current=next;save();render();}catch{notify('invalid');}});
  const sharing=el('details','','pd-passport');sharing.append(el('summary',t().passport));body.append(sharing);checkbox(sharing,'includePrompt',current.includePrompt,value=>edit(()=>current.includePrompt=value));checkbox(sharing,'includeSettings',current.includeSettings,value=>edit(()=>current.includeSettings=value));passport=field(sharing,'passportPreview','','textarea',null,'passport');passport.readOnly=true;passport.rows=8;button(sharing,'copy',()=>copy(passport.value));
  const checklist=el('fieldset','','pd-checklist');checklist.append(el('legend',t().checklist));for(const key of publicationChecks)checkbox(checklist,'check-'+key,current.checks[key],value=>edit(()=>current.checks[key]=value),key);body.append(checklist);progress=el('p','','pd-progress');body.append(progress);
  const exports=el('div','','pd-actions');body.append(exports);button(exports,'export',()=>{try{download(publicationZip(exportPublicationFiles(current)),publicationReady(current)?'_publication.zip':'_DRAFT_publication.zip','application/zip');}catch{notify('saveError');}});button(exports,'backup',()=>download(JSON.stringify({type:'PromptStudioPublicationDraft',version:1,draft:normalizePublicationDraft(current)},null,2),'_PRIVATE_draft.json','application/json'));const importInput=el('input');importInput.type='file';importInput.accept='.json,application/json';importInput.hidden=true;exports.append(importInput);button(exports,'importDraft',()=>{importInput.value='';importInput.click();});importInput.addEventListener('change',async()=>{try{const file=importInput.files?.[0];if(!file)return;if(file.size>300000)throw Error('format');const draft=parsePublicationDraft(await file.text());capture(draft);}catch{notify('invalid');}});body.append(el('p',t().exportHelp,'pd-help'),status);status.textContent=t()[statusKey]||'';refresh();
 }
 document.getElementById('ui-language')?.addEventListener('change',render);globalThis.addEventListener?.('beforeunload',event=>{if(pending){event.preventDefault();event.returnValue='';}});

 function list(){const fresh=createPublicationStore(storage);if(fresh.problem())throw Error('storage');return fresh.list().map(d=>({...d,ready:publicationReady(d)}));}
 function resume(id,{scroll=true}={}){if(!canLeave())return false;try{const fresh=createPublicationStore(storage);if(fresh.problem())throw Error('storage');const found=fresh.list().find(p=>p.id===id);if(!found)return false;store=fresh;select(found);root.open=true;if(scroll)root.scrollIntoView({behavior:'smooth',block:'start'});return true;}catch{notify('saveError');return false;}}
 render();return {list,resume,captureArchive:item=>capture(publicationFromArchive(item)),captureSeries:project=>capture(publicationFromSeries(project)),labels:()=>t(),getState:()=>normalizePublicationDraft(current),seriesStatus:(project,drafts)=>publicationSeriesStatus(project,drafts||store.list()),open};
}
